function handleLogoTripleClick(){logoTripleClickCounter++;if(logoTripleClickCounter===1){logoTripleClickTimer=setTimeout(()=>{logoTripleClickCounter=0;},900);}else if(logoTripleClickCounter===3){clearTimeout(logoTripleClickTimer);logoTripleClickCounter=0;openAdminSection('account-management-section');}}

// دالة تشغيل فيديو البداية والانتقال التلقائي لشاشة الدخول بعد 10 ثوانٍ أو عند انتهاء الفيديو
function startSplashScreen(){
  const vSplash = document.getElementById('video-splash-screen');
  const video = document.getElementById('introVideo');
  if(!vSplash) return showLoginScreen();
  
  // تشغيل الفيديو تلقائياً
  if(video) {
    video.play().catch(()=>{});
    video.onended = endVideoSplash;
  }
  // مؤقت أمان 10 ثوانٍ كحد أقصى
  setTimeout(endVideoSplash, 10000);
}

// دالة إنهاء فيديو البداية والانتقال لشاشة الدخول
function endVideoSplash(){
  const vSplash = document.getElementById('video-splash-screen');
  if(!vSplash || vSplash.style.display === 'none') return;
  vSplash.style.opacity = '0';
  setTimeout(()=>{
    vSplash.style.display = 'none';
    showLoginScreen();
  }, 800);
}
function showLoginScreen(){const loginScreen=document.getElementById('login-screen');if(loginScreen){loginScreen.style.display='flex';}const passInp=document.getElementById('loginPass');if(passInp){passInp.focus();}}

function login(){const u=(document.getElementById('loginUser')?.value||'').trim();const p=(document.getElementById('loginPass')?.value||'').trim();const err=document.getElementById('loginError');let foundUser=globalUsers.find(user=>user.Username===u&&String(user.Password)===p);if(!foundUser){if(u.toLowerCase()==='admin'&&p==='1234')foundUser={Role:'Admin',Username:'Admin'};else if((u.toLowerCase()==='safety'||u==='سلامة المطارات')&&p==='1234')foundUser={Role:'Airport Safety',Username:u};else if((u.toLowerCase()==='osh'||u==='السلامة والصحة المهنية')&&p==='1234')foundUser={Role:'OSH',Username:u};else if((u.toLowerCase()==='env'||u==='البيئة والحياة البرية')&&p==='1234')foundUser={Role:'Environment',Username:u};else if((u.toLowerCase()==='fire'||u==='الحماية المدنية')&&p==='1234')foundUser={Role:'Civil Defense',Username:u};else if(globalUsers.length===0&&p==='1234')foundUser={Role:'Admin',Username:u};}if(foundUser){currentLoggedInUser=foundUser;const lS=document.getElementById('login-screen');if(lS)lS.style.display='none';const hdr=document.getElementById('app-header');if(hdr)hdr.style.display='flex';if(err)err.style.display='none';const bBtn=document.getElementById('backToMainBtn');const r=(foundUser.Role||'').toLowerCase();if(r.includes('admin')){if(bBtn)bBtn.style.display='inline-block';openSection('main-dashboard');}else if(r.includes('safety')||r.includes('مطارات')){if(bBtn)bBtn.style.display='none';openSection('airport-safety-dashboard');}else if(r.includes('osh')||r.includes('صحة')||r.includes('مهنية')){openGenericDoc('السلامة والصحة المهنية','main-dashboard');}else if(r.includes('env')||r.includes('بيئة')||r.includes('برية')){openGenericDoc('البيئة والحياة البرية','main-dashboard');}else if(r.includes('fire')||r.includes('حماية')||r.includes('مدنية')){openGenericDoc('الحماية المدنية','main-dashboard');}else{if(bBtn)bBtn.style.display='inline-block';openSection('main-dashboard');}}else{if(err)err.style.display='block';const pInp=document.getElementById('loginPass');if(pInp){pInp.value='';pInp.focus();}}}

function logout(){currentLoggedInUser=null;document.querySelectorAll('.content-area').forEach(el=>el.style.display='none');const hdr=document.getElementById('app-header');if(hdr)hdr.style.display='none';const pInp=document.getElementById('loginPass');if(pInp)pInp.value='';const lS=document.getElementById('login-screen');if(lS)lS.style.display='flex';}

function toggleLoginPassword(){const p=document.getElementById('loginPass'),i=document.getElementById('passToggleIcon');if(!p||!i)return;p.type=p.type==='password'?'text':'password';i.classList.toggle('fa-eye');i.classList.toggle('fa-eye-slash');}

function safePost(p,b,m,sM,cb){if(b){b.disabled=true;b.dataset.oH=b.innerHTML;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ...';}fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(p)}).then(()=>{if(m){m.innerText=sM||'تم بنجاح!';m.style.color='green';m.style.display='block';setTimeout(()=>m.style.display='none',3000);}if(cb)cb();}).catch(err=>{console.error(err);if(m){m.innerText='حدث خطأ في الاتصال!';m.style.color='red';m.style.display='block';}}).finally(()=>{if(b){b.disabled=false;if(b.dataset.oH)b.innerHTML=b.dataset.oH;}});}

function openSection(sId){document.querySelectorAll('.content-area').forEach(el=>el.style.display='none');const t=document.getElementById(sId);if(t){t.style.display='block';window.scrollTo({top:0,behavior:'smooth'});}}

function openAdminSection(sId){openSection(sId);}

function openGenericDoc(t,bT){genericBackTarget=bT||'main-dashboard';const el=document.getElementById('generic-doc-title');if(el)el.innerText=t;openSection('generic-doc-section');}

function goBackFromGenericDoc(){openSection(genericBackTarget||'main-dashboard');}

function openQuarterlyCompany(cType){document.getElementById('quarterlyCompanyType').value=cType;const titleEl=document.getElementById('quarterlyCompanyTitle');if(titleEl)titleEl.innerText=cType==='ground'?'تقارير التفتيش الربع سنوي - شركة الخدمات الأرضية':'تقارير التفتيش الربع سنوي - شركة تموين الوقود';renderQuarterlyReports(cType);const box=document.getElementById('quarterly-company-box');if(box){box.style.display='block';box.scrollIntoView({behavior:'smooth'});}}

function viewQuarterlyPdf(url, fileName){if(!url)return alert('رابط المستند غير صالح!');if(url.startsWith('http')){window.open(url,'_blank');return;}try{let base64Parts=url.split(',');let base64Str=base64Parts.length>1?base64Parts[1]:base64Parts[0];let byteCharacters=atob(base64Str);let byteNumbers=new Array(byteCharacters.length);for(let i=0;i<byteCharacters.length;i++){byteNumbers[i]=byteCharacters.charCodeAt(i);}let byteArray=new Uint8Array(byteNumbers);let blob=new Blob([byteArray],{type:'application/pdf'});let blobUrl=URL.createObjectURL(blob);window.open(blobUrl,'_blank');setTimeout(()=>URL.revokeObjectURL(blobUrl),60000);}catch(e){console.error(e);alert('تعذر فتح المستند، يرجى المحاولة مرة أخرى.');}}

function renderQuarterlyReports(cType){const tb=document.getElementById('quarterly-reports-tbody');if(!tb)return;tb.innerHTML='';const list=globalQuarterlyDocs[cType]||[];if(list.length===0){tb.innerHTML='<tr><td colspan="5" style="text-align:center;padding:12px;color:#777;">لا توجد تقارير PDF محفوظة لهذه الشركة بعد</td></tr>';return;}list.forEach((doc,idx)=>{tb.innerHTML+=`<tr style="text-align:center;border-bottom:1px solid #eee;"><td style="padding:6px;" dir="ltr">${doc.date||'-'}</td><td style="padding:6px;font-weight:bold;color:#003366;">${doc.quarter||'-'}</td><td style="padding:6px;">${doc.inspector||'-'}</td><td style="padding:6px;"><button type="button" onclick="viewQuarterlyPdf(globalQuarterlyDocs['${cType}'][${idx}].url, '${doc.name||'Report'}')" style="background:#dc3545;color:#fff;border:none;padding:5px 12px;border-radius:4px;font-weight:bold;font-size:10.5px;cursor:pointer;"><i class="fa-solid fa-file-pdf"></i> فتح PDF</button></td><td style="padding:6px;"><button type="button" onclick="deleteQuarterlyDoc('${cType}', ${idx})" style="background:#888;color:#fff;border:none;padding:3px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-trash"></i></button></td></tr>`;});}

async function uploadQuarterlyPdf(){const cType=document.getElementById('quarterlyCompanyType').value;const dateVal=document.getElementById('quarterlyDate').value;const qVal=document.getElementById('quarterlyQuarter').value;const inspVal=document.getElementById('quarterlyInspector').value;const fileInp=document.getElementById('quarterlyPdfFile');const btn=document.getElementById('uploadQuarterlyBtn');const msg=document.getElementById('quarterlyUploadMsg');if(!fileInp.files||!fileInp.files[0])return alert("يرجى اختيار ملف PDF للتقرير!");const file=fileInp.files[0];btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري رفع التقرير وحفظه...';const reader=new FileReader();reader.onload=async e=>{const base64Data=e.target.result;try{await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:"uploadQuarterlyDoc",companyType:cType,date:dateVal,quarter:qVal,inspector:inspVal,fileName:file.name,fileData:base64Data,mimeType:"application/pdf"})});const newDoc={date:dateVal,quarter:qVal,inspector:inspVal,name:file.name,url:base64Data};if(!globalQuarterlyDocs[cType])globalQuarterlyDocs[cType]=[];globalQuarterlyDocs[cType].unshift(newDoc);try{localStorage.setItem('rmf_quarterly_docs',JSON.stringify(globalQuarterlyDocs));}catch(err){}renderQuarterlyReports(cType);fileInp.value='';msg.innerText="✅ تم حفظ تقرير الـ PDF بنجاح في جوجل درايف وقاعدة البيانات!";msg.style.color="#28a745";setTimeout(()=>msg.innerText="",3500);}catch(err){alert("❌ فشل رفع التقرير!");}finally{btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> رفع وحفظ تقرير التفتيش (PDF)';}};reader.readAsDataURL(file);}

function deleteQuarterlyDoc(cType,idx){if(!confirm("تأكيد حذف تقرير التفتيش هذا؟"))return;globalQuarterlyDocs[cType].splice(idx,1);try{localStorage.setItem('rmf_quarterly_docs',JSON.stringify(globalQuarterlyDocs));}catch(e){}renderQuarterlyReports(cType);}

function populateFilterSelect(elId, dataArray, key1, key2){const el=document.getElementById(elId);if(!el||!dataArray)return;let vals=new Set();dataArray.forEach(item=>{let v=(item[key1]||item[key2]||'').toString().trim();if(v&&v!=='-')vals.add(v);});el.innerHTML='<option value="ALL">الكل</option>';Array.from(vals).sort().forEach(v=>{el.innerHTML+=`<option value="${v}">${v}</option>`;});}

function loadAppDataInit(){try{const cInc=localStorage.getItem('rmf_incidents');if(cInc){const p=JSON.parse(cInc);if(Array.isArray(p)&&p.length>0){globalIncidents=p;window.globalIncidents=p;sortIncidentsByDate();renderSavedIncidents();updateIncidentNavCounter();}}const cQ=localStorage.getItem('rmf_quarterly_docs');if(cQ)globalQuarterlyDocs=JSON.parse(cQ);}catch(e){}const cb='jsonpInit_'+Math.round(100000*Math.random());window[cb]=function(d){try{if(d&&d.status==="success"){globalFleetData=d.fleet?d.fleet.reverse():[];globalSurveys=d.surveys?d.surveys.reverse():[];globalUsers=d.users||[];if(d.incidents&&Array.isArray(d.incidents)&&d.incidents.length>0){globalIncidents=d.incidents;window.globalIncidents=d.incidents;try{localStorage.setItem('rmf_incidents',JSON.stringify(globalIncidents));}catch(e){}}globalFod=d.fod||[];globalSpiData=d.spi||[];if(d.quarterly&&Array.isArray(d.quarterly)&&d.quarterly.length>0){let qObj={ground:[],fuel:[]};d.quarterly.forEach(row=>{let cT=(row.Company_Type||'').toLowerCase();let dItem={date:row.Date,quarter:row.Quarter,inspector:row.Inspector,name:row.File_Name,url:row.File_URL};if(cT.includes('fuel'))qObj.fuel.push(dItem);else qObj.ground.push(dItem);});globalQuarterlyDocs=qObj;try{localStorage.setItem('rmf_quarterly_docs',JSON.stringify(globalQuarterlyDocs));}catch(e){}}sortIncidentsByDate();if(d.daily&&d.daily.length>0){let rMap={};d.daily.forEach(row=>{let repId=row.Report_ID,timeStr=row.Time;if(timeStr&&typeof timeStr==='string'&&timeStr.includes('T')){let dt=new Date(timeStr);if(!isNaN(dt))timeStr=dt.toISOString().substring(11,16);}if(!rMap[repId])rMap[repId]={id:repId,date:row.Date?new Date(row.Date).toISOString().split('T')[0]:'',time:timeStr,shift:row.Shift,inspector:row.Inspector,findings:[]};if(row.Category&&row.Category!=="لا توجد ملاحظات")rMap[repId].findings.push({category:row.Category,item:row.Finding_Item,location:row.Location,responsible:row.Responsible,note:row.Corrective_Action||"",status:row.Status||"مفتوح"});});globalDailyInspections=Object.values(rMap).sort((a,b)=>b.id-a.id);}populateUsersDropdown(globalUsers);updateSurveyNavCounter();buildSpiEntryForm();renderSavedDaily();renderSavedIncidents();updateDailyNavCounter();updateIncidentNavCounter();populateFilterSelect('incFilterCar',globalIncidents,'CAR','car');populateFilterSelect('incFilterReg',globalIncidents,'REG','reg');populateFilterSelect('surveyFilterAirline',globalSurveys,'CAR','car');populateFilterSelect('surveyFilterReg',globalSurveys,'REG','reg');}}catch(e){console.error(e);}finally{delete window[cb];}};const s=document.createElement('script');s.src=API_URL+"?action=getAppData&_t="+Date.now()+"&callback="+cb;document.body.appendChild(s);}

function sortIncidentsByDate(){if(!globalIncidents)return;globalIncidents.sort((a,b)=>{let da=new Date(a.Date||a.date||0).getTime(),db=new Date(b.Date||b.date||0).getTime();return db-da;});window.globalIncidents=globalIncidents;}

function updateSurveyNavCounter(){const el=document.getElementById('nav-counter');if(el)el.innerText=globalSurveys.length>0?`${currentSurveyIndex+1} / ${globalSurveys.length}`:`0 / 0`;}

function navSurveys(dir){if(!globalSurveys||globalSurveys.length===0)return alert("لا توجد استبيانات مسجلة بعد.");if(dir==='first')currentSurveyIndex=0;else if(dir==='last')currentSurveyIndex=globalSurveys.length-1;else if(dir==='next'&&currentSurveyIndex<globalSurveys.length-1)currentSurveyIndex++;else if(dir==='prev'&&currentSurveyIndex>0)currentSurveyIndex--;if(currentSurveyIndex>=0&&currentSurveyIndex<globalSurveys.length){displaySurveyInForm(globalSurveys[currentSurveyIndex]);updateSurveyNavCounter();isSurveyEditMode=false;let b=document.getElementById('submitSurveyBtn'),eBtn=document.getElementById('editSurveyBtn');if(b){b.disabled=true;b.innerHTML='<i class="fa-solid fa-eye"></i> وضع العرض';b.style.backgroundColor="#6c757d";}if(eBtn)eBtn.style.display='block';}}

function displaySurveyInForm(s){if(!s)return;currentSurveyEditId=s.ID||s.id||null;let dStr=(s.Date||'').toString().trim();if(dStr.includes('T'))dStr=dStr.split('T')[0];document.getElementById('capDate').value=dStr;let tStr=(s.Time||'').toString().trim();if(tStr.includes('T')){let tPart=tStr.split('T')[1];tStr=tPart.substring(0,5);}else if(tStr.includes(':')){let tp=tStr.split(':');let hh=tp[0].trim();if(hh.length===1)hh='0'+hh;tStr=hh+':'+tp[1].substring(0,2);}document.getElementById('capTime').value=tStr;document.getElementById('fltNo').value=s.Flight_NO||'';document.getElementById('reg').value=s.REG||'';document.getElementById('airline').value=s.CAR||'';document.getElementById('acType').value=s.TYPE||'';document.getElementById('comments').value=s.Captain_Comments||'';criteriaList.forEach(c=>{let v=s[c]||"Blank",r=document.querySelector(`input[name="${c}"][value="${v}"]`);if(r)r.checked=true;});}

function enableSurveyEdit(){isSurveyEditMode=true;let b=document.getElementById('submitSurveyBtn'),eBtn=document.getElementById('editSurveyBtn');if(b){b.disabled=false;b.innerHTML='<i class="fa-solid fa-pen-to-square"></i> تحديث بيانات الاستبيان';b.style.backgroundColor="#e67e22";}if(eBtn)eBtn.style.display='none';}

function clearFormForNew(){currentSurveyIndex=-1;isSurveyEditMode=false;currentSurveyEditId=null;document.getElementById('surveyForm').reset();updateSurveyNavCounter();let b=document.getElementById('submitSurveyBtn'),eBtn=document.getElementById('editSurveyBtn');if(b){b.disabled=false;b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ بيانات الاستبيان';b.style.backgroundColor="var(--primary)";}if(eBtn)eBtn.style.display='none';let now=new Date().toISOString();document.getElementById('capDate').value=now.split('T')[0];document.getElementById('capTime').value=now.split('T')[1].substring(0,5);}

function submitSurvey(e){if(e)e.preventDefault();const btn=document.getElementById('submitSurveyBtn'),msg=document.getElementById('surveyMsg'),reg=document.getElementById('reg').value.toUpperCase().trim(),airline=document.getElementById('airline').value.toUpperCase().trim(),type=document.getElementById('acType').value.toUpperCase().trim();if(!reg||!airline)return alert("يرجى إدخال حروف التسجيل وشركة الطيران!");let sObj={"id":isSurveyEditMode?currentSurveyEditId:null,"Date":document.getElementById('capDate').value,"Time":document.getElementById('capTime').value,"Flight_NO":document.getElementById('fltNo').value,"REG":reg,"CAR":airline,"TYPE":type,"Captain_Comments":document.getElementById('comments').value};criteriaList.forEach(crit=>{let sel=document.querySelector(`input[name="${crit}"]:checked`);sObj[crit]=sel?sel.value:"Blank";});safePost({action:isSurveyEditMode?"updateSurvey":"submitSurvey",surveyData:sObj},btn,msg,"تم الحفظ وحفظ الطائرة بنجاح!",(res)=>{if(isSurveyEditMode){let exIdx=globalSurveys.findIndex(x=>(x.ID||x.id)===currentSurveyEditId);if(exIdx>-1)globalSurveys[exIdx]=sObj;}else{sObj.ID=res?res.id:("S-"+Date.now());globalSurveys.unshift(sObj);}let exists=globalFleetData.some(a=>(a.REG||'').toString().toUpperCase().trim()===reg);if(!exists){globalFleetData.unshift({REG:reg,TYPE:type,CAR:airline,Handling:'EMAAS',Country:'-'});populateFilterSelect('surveyFilterReg',globalFleetData,'REG','reg');populateFilterSelect('surveyFilterAirline',globalFleetData,'CAR','car');}updateSurveyNavCounter();setTimeout(()=>clearFormForNew(),1500);});}

