function setupCustomDropdown(){const inp=document.getElementById('reg'),arr=document.getElementById('regArrowBtn'),lst=document.getElementById('regDropdownList');if(inp&&arr&&lst){arr.addEventListener('click',e=>{e.stopPropagation();lst.classList.toggle('show');filterRegOptions(true);});inp.addEventListener('input',()=>{lst.classList.add('show');filterRegOptions(false);let val=inp.value.toUpperCase().trim();let f=globalFleetData.find(a=>(a.REG||'').toString().toUpperCase().trim()===val);if(f){document.getElementById('airline').value=f.CAR||'';document.getElementById('acType').value=f.TYPE||'';}});document.addEventListener('click',()=>lst.classList.remove('show'));}}

