function generateModernReport(){let fromD=document.getElementById('fromDate').value,toD=document.getElementById('toDate').value;if(!fromD||!toD)return alert("اختر الفترة أولاً");let fd=new Date(fromD),td=new Date(toD);td.setHours(23,59,59,999);let selAir=document.getElementById('surveyFilterAirline')?.value||'ALL',selReg=document.getElementById('surveyFilterReg')?.value||'ALL';document.getElementById('printable-report').style.display='block';let flt=globalSurveys.filter(s=>{let sd=new Date(s.Date);let cAir=(selAir==='ALL')||(s.CAR===selAir);let cReg=(selReg==='ALL')||(s.REG===selReg);return sd>=fd&&sd<=td&&cAir&&cReg;});document.getElementById('report-date-range').innerText=`الفترة من ${fromD} إلى ${toD}`;document.getElementById('stat-total').innerText=flt.length;let aC={},dC={},eC={"Excellent":0,"Good":0,"Poor":0,"N/A":0,"Blank":0},cList=[];const tb=document.getElementById('flights-eval-tbody');tb.innerHTML='';let mS={"Excellent":{},"Good":{},"Poor":{},"N/A":{},"Blank":{}};criteriaList.forEach(crit=>{mS["Excellent"][crit]=0;mS["Good"][crit]=0;mS["Poor"][crit]=0;mS["N/A"][crit]=0;mS["Blank"][crit]=0;});flt.forEach(s=>{if(s.CAR)aC[s.CAR]=(aC[s.CAR]||0)+1;let ds=s.Date?String(s.Date).split('T')[0]:'Unknown';dC[ds]=(dC[ds]||0)+1;let fC={"Excellent":0,"Good":0,"Poor":0,"N/A":0,"Blank":0};criteriaList.forEach(crit=>{let v=s[crit]||"Blank";if(fC[v]!==undefined)fC[v]++;if(eC[v]!==undefined)eC[v]++;if(mS[v])mS[v][crit]++;});if(s.Captain_Comments&&s.Captain_Comments.trim()!=="")cList.push(s);tb.innerHTML+=`<tr><td><b>${s.CAR||''}</b></td><td>${s.Flight_NO||''}</td><td>${ds}</td><td>${s.REG||''}</td><td style="color:#28a745;font-weight:bold;">${fC["Excellent"]}</td><td style="color:#ffc107;font-weight:bold;">${fC["Good"]}</td><td style="color:#dc3545;font-weight:bold;">${fC["Poor"]}</td><td>${fC["N/A"]}</td><td>${fC["Blank"]}</td></tr>`;});document.getElementById('stat-airlines').innerText=Object.keys(aC).length;let totE=Object.values(eC).reduce((a,b)=>a+b,0);document.getElementById('stat-excellent').innerText=`${totE>0?Math.round((eC["Excellent"]/totE)*100):0}%`;if(chartInstances.air)chartInstances.air.destroy();if(chartInstances.dates)chartInstances.dates.destroy();if(chartInstances.eval)chartInstances.eval.destroy();Chart.defaults.font.family="'Cairo', sans-serif";let ctxEval=document.getElementById('evalChart')?.getContext('2d');if(ctxEval){chartInstances.eval=new Chart(ctxEval,{type:'doughnut',data:{labels:['ممتاز','جيد','ضعيف','غير منطبق','فارغ'],datasets:[{data:[eC["Excellent"]||0,eC["Good"]||0,eC["Poor"]||0,eC["N/A"]||0,eC["Blank"]||0],backgroundColor:['#28a745','#ffc107','#dc3545','#6c757d','#003366'],borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top',labels:{boxWidth:12,font:{size:10}}}}}});}let ctxAir=document.getElementById('airlinesChart')?.getContext('2d');if(ctxAir){chartInstances.air=new Chart(ctxAir,{type:'bar',data:{labels:Object.keys(aC),datasets:[{label:'الاستبيانات',data:Object.values(aC),backgroundColor:'#003366',borderRadius:4}]},options:{responsive:true,maintainAspectRatio:false}});}let ctxDates=document.getElementById('datesChart')?.getContext('2d');if(ctxDates){chartInstances.dates=new Chart(ctxDates,{type:'line',data:{labels:Object.keys(dC).sort(),datasets:[{label:'النشاط اليومي',data:Object.keys(dC).sort().map(d=>dC[d]),borderColor:'#f39c12',tension:0.3}]},options:{responsive:true,maintainAspectRatio:false}});}let eH=`<div class="avoid-page-break" style="margin-top:35px;direction:ltr;"><h3 style="color:#003366;text-align:center;margin-bottom:12px;font-size:1.2rem;">Safety Captain Survey Report Evaluation Matrix</h3><table style="width:100%;border-collapse:collapse;border:1px solid #777;font-size:11px;text-align:center;"><thead><tr style="background:#003366;color:#fff;"><th style="padding:8px;border:1px solid #999;text-align:left;width:40%;">Evaluation Criteria</th><th style="padding:8px;border:1px solid #999;background:#28a745;">Excellent</th><th style="padding:8px;border:1px solid #999;background:#ffc107;color:#000;">Good</th><th style="padding:8px;border:1px solid #999;background:#dc3545;">Poor</th><th style="padding:8px;border:1px solid #999;background:#6c757d;">N/A</th><th style="padding:8px;border:1px solid #999;background:#1a2a6c;">Blank</th></tr></thead><tbody>`;criteriaList.forEach(crit=>{eH+=`<tr><td style="padding:6px 10px;border:1px solid #ccc;text-align:left;font-weight:bold;background:#f9f9f9;">${crit}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Excellent"][crit]>0?'#28a745':'#aaa'};">${mS["Excellent"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Good"][crit]>0?'#ffc107':'#aaa'};">${mS["Good"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;font-weight:bold;color:${mS["Poor"][crit]>0?'#dc3545':'#bbb'};">${mS["Poor"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;color:#555;">${mS["N/A"][crit]||0}</td><td style="padding:6px;border:1px solid #ccc;color:#555;">${mS["Blank"][crit]||0}</td></tr>`;});eH+=`</tbody></table></div><div class="avoid-page-break" style="margin-top:35px;direction:ltr;text-align:left;"><h3 style="color:#003366;margin-bottom:10px;">Captain Comments & Observations:</h3><table class="avoid-page-break" style="width:100%;border-collapse:collapse;border:1px solid #000;font-size:11px;"><thead style="background:#e6e6e6;"><tr><th style="border:1px solid #000;padding:6px;">Airline</th><th style="border:1px solid #000;padding:6px;">FLTNO</th><th style="border:1px solid #000;padding:6px;">Type</th><th style="border:1px solid #000;padding:6px;">Date</th><th style="border:1px solid #000;padding:6px;">REG</th><th style="border:1px solid #000;padding:6px;">Comments</th></tr></thead><tbody>`;if(cList.length===0)eH+=`<tr><td colspan="6" style="text-align:center;">No comments.</td></tr>`;else cList.forEach(s=>{eH+=`<tr><td style="border:1px solid #000;padding:6px;">${s.CAR||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Flight_NO||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.TYPE||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Date?String(s.Date).split('T')[0]:''}</td><td style="border:1px solid #000;padding:6px;">${s.REG||'-'}</td><td style="border:1px solid #000;padding:6px;">${s.Captain_Comments}</td></tr>`;});eH+=`</tbody></table></div>`;document.getElementById('additional-tables-container').innerHTML=eH;}

