function buildDailyChecklist() { const grid = document.getElementById('checklist-container'); if (!grid) return; grid.innerHTML = ""; let checkIndex = 0; Object.keys(dailyChecklistData).forEach(colKey => { let colData = dailyChecklistData[colKey]; let colHTML = `<div class="checklist-column">`; const renderSection = (title, items) => { colHTML += `<div class="checklist-header">${title}</div>`; items.forEach(item => { let rOpts = responsibleDepts.map(d => `<option value="${d}">${d}</option>`).join(''); colHTML += `<div class="check-item"><div class="check-item-row"><input type="checkbox" id="chk_${checkIndex}" value="${title}|${item}" onchange="toggleInputs(${checkIndex})"><label for="chk_${checkIndex}">${item}</label></div><div id="inputs_${checkIndex}" class="check-inputs" style="display:none; flex-direction:column; gap:8px; margin-top:8px; padding:10px; background:#fdfdfd; border-right:4px solid #dc3545; border-radius:4px;"><input type="text" id="note_${checkIndex}" placeholder="تفاصيل الملاحظة..." style="width:100%; padding:7px; border:1px solid #ccc; border-radius:4px; box-sizing:border-box;"><div style="display:flex; gap:5px;"><select id="resp_${checkIndex}" style="flex:1; padding:7px; border:1px solid #ccc; border-radius:4px;"><option value="" disabled selected>الجهة المسئولة...</option>${rOpts}</select><input type="text" id="loc_${checkIndex}" placeholder="المكان (Location)..." style="flex:1; padding:7px; border:1px solid #ccc; border-radius:4px;"></div><input type="hidden" id="actionTaken_${checkIndex}" value=""><input type="hidden" id="status_${checkIndex}" value="مفتوح"><button type="button" id="rectifyBtn_${checkIndex}" onclick="toggleRectifyFinding(this, ${checkIndex})" style="background:#28a745; color:#fff; border:none; padding:8px; border-radius:6px; cursor:pointer; font-weight:bold; width:100%; display:flex; align-items:center; justify-content:center; gap:6px;"><i class="fa-solid fa-circle-check"></i> إغلاق وتلافي هذه الملاحظة الآن</button></div></div>`; checkIndex++; }); }; renderSection(colData.title, colData.items); if (colData.title2) renderSection(colData.title2, colData.items2); if (colData.title3) renderSection(colData.title3, colData.items3); colHTML += `</div>`; grid.innerHTML += colHTML; }); }

function toggleRectifyFinding(btn, idx) { let statusInput = document.getElementById(`status_${idx}`); if (!statusInput) { statusInput = document.createElement('input'); statusInput.type = 'hidden'; statusInput.id = `status_${idx}`; statusInput.value = 'مفتوح'; btn.parentNode.appendChild(statusInput); } let today = new Date().toISOString().split('T')[0]; let actionInput = document.getElementById(`actionTaken_${idx}`); if (statusInput.value !== 'مغلق') { statusInput.value = 'مغلق'; btn.style.backgroundColor = '#155724'; btn.innerHTML = `<i class="fa-solid fa-check-double"></i> تم تلافي وإغلاق الملاحظة بتاريـخ (${today})`; if (actionInput) actionInput.value = `[تم تلافي الملحوظة بتاريخ ${today}]`; } else { statusInput.value = 'مفتوح'; btn.style.backgroundColor = '#28a745'; btn.innerHTML = `<i class="fa-solid fa-circle-check"></i> إغلاق وتلافي هذه الملاحظة الآن`; if (actionInput) actionInput.value = ''; } }

