function clearDailyFormForNew(){currentDailyIndex=-1;isDailyEditMode=false;currentDailyEditId=null;document.getElementById('dailyForm').reset();document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach(c=>c.checked=false);document.querySelectorAll('.check-inputs').forEach(el=>el.style.display='none');let b=document.getElementById('submitDailyBtn');if(b){b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ الجولة';b.style.backgroundColor="var(--primary)";}let now=new Date().toISOString();document.getElementById('dailyDate').value=now.split('T')[0];document.getElementById('dailyTime').value=now.split('T')[1].substring(0,5);updateDailyNavCounter();}

function navDaily(dir){if(!globalDailyInspections||globalDailyInspections.length===0)return alert("لا توجد فحوصات مسجلة.");if(dir==='first')currentDailyIndex=0;else if(dir==='last')currentDailyIndex=globalDailyInspections.length-1;else if(dir==='next'&&currentDailyIndex<globalDailyInspections.length-1)currentDailyIndex++;else if(dir==='prev'&&currentDailyIndex>0)currentDailyIndex--;if(currentDailyIndex>=0&&currentDailyIndex<globalDailyInspections.length)loadDailyInspectionToForm(currentDailyIndex);}

function loadDailyInspectionToForm(idx){if(!globalDailyInspections||idx<0||idx>=globalDailyInspections.length)return;currentDailyIndex=idx;let rep=globalDailyInspections[currentDailyIndex];if(!rep)return;if(typeof switchDailyTab==='function')switchDailyTab('entry');const f=document.getElementById('dailyForm');if(f)f.reset();document.querySelectorAll('.check-inputs').forEach(el=>el.style.display='none');const dD=document.getElementById('dailyDate'),dT=document.getElementById('dailyTime'),dS=document.getElementById('dailyShift'),dI=document.getElementById('dailyInspector');if(dD)dD.value=rep.date||'';if(dT)dT.value=rep.time||'';if(dS)dS.value=rep.shift||'صباحي';if(dI)dI.value=rep.inspector||'';if(rep.findings&&rep.findings.length>0){document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk,chkIdx)=>{let parts=chk.value.split('|');let cat=parts[0].trim(),itm=parts[1].trim();let found=rep.findings.find(x=>(x.category||'').trim()===cat&&(x.item||'').trim()===itm);if(found){chk.checked=true;let inDiv=document.getElementById(`inputs_${chkIdx}`);if(inDiv){inDiv.style.display='flex';if(!document.getElementById(`btn_close_${chkIdx}`)){let qBtn=document.createElement('button');qBtn.id=`btn_close_${chkIdx}`;qBtn.type='button';qBtn.innerHTML='<i class="fa-solid fa-check-circle"></i> إغلاق وتلافي هذه الملاحظة الآن';qBtn.style.cssText="background:#28a745;color:white;border:none;padding:5px 10px;border-radius:4px;cursor:pointer;font-weight:bold;margin-top:5px;font-size:0.8rem;";qBtn.onclick=function(){quickCloseFinding(chkIdx);};inDiv.appendChild(qBtn);}}let fn=found.note||"",nT="تم الرصد",aT="لم يحدد",tD="غير محدد";try{let m=fn.match(/الملاحظة: (.*?) - الإجراء: (.*?) - تاريخ التلافي: (.*)/);if(m){nT=m[1];aT=m[2];tD=m[3];}else{nT=fn;}}catch(e){}if(document.getElementById(`note_${chkIdx}`))document.getElementById(`note_${chkIdx}`).value=nT;if(document.getElementById(`actionTaken_${chkIdx}`))document.getElementById(`actionTaken_${chkIdx}`).value=(aT!=="لم يحدد")?aT.replace(/\[تم تلافي الملحوظة بتاريخ.*?\]/g,'').trim():"";let df=document.getElementById(`targetDate_${chkIdx}`);if(df)df.value=(tD!=="غير محدد"&&tD.trim()!=="")?tD:"";if(document.getElementById(`loc_${chkIdx}`))document.getElementById(`loc_${chkIdx}`).value=found.location||"";if(document.getElementById(`resp_${chkIdx}`))document.getElementById(`resp_${chkIdx}`).value=found.responsible||"";let st=document.getElementById(`status_${chkIdx}`);if(st){st.value=found.status||"مفتوح";if(typeof updateStatusColor==='function')updateStatusColor(st);else{st.style.backgroundColor=(st.value==='مغلق'?'#28a745':'#dc3545');st.style.color='#fff';}}}});}if(typeof updateDailyNavCounter==='function')updateDailyNavCounter();isDailyEditMode=true;currentDailyEditId=rep.id;let btn=document.getElementById('submitDailyBtn');if(btn){btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-pen-to-square"></i> حفظ التعديلات وتحديث الحالة';btn.style.backgroundColor="#ffc107";btn.style.color="#000";}if(f)f.scrollIntoView({behavior:'smooth',block:'start'});}

function getMonthlyUniqueAuditStats(month,year){let uniqueMap={};if(!globalDailyInspections)return{total:0,closed:0,pending:0};globalDailyInspections.forEach(rep=>{if(!rep.date)return;let d=new Date(rep.date);if(isNaN(d))return;if((d.getMonth()+1)===parseInt(month)&&d.getFullYear()===parseInt(year)){if(rep.findings&&rep.findings.length>0){rep.findings.forEach(f=>{let key=((f.category||'').trim()+'___'+(f.item||'').trim()+'___'+(f.location||'').trim()).toLowerCase();let isCl=(String(f.status||f.Status||'').trim()==='مغلق'||String(f.status||f.Status||'').trim().toLowerCase()==='closed'||String(f.note||'').includes('تم تلافي')||String(f.actionTaken||f.action||'').includes('تم تلافي'));if(!uniqueMap[key]){uniqueMap[key]={isClosed:isCl};}else{if(isCl)uniqueMap[key].isClosed=true;}});}}});let total=0,closed=0,pending=0;Object.keys(uniqueMap).forEach(k=>{total++;if(uniqueMap[k].isClosed){closed++;}else{pending++;}});return{total:total,closed:closed,pending:pending};}

async function submitDailyInspection(e) { e.preventDefault(); const btn = document.getElementById('submitDailyBtn'); btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري الحفظ...'; btn.disabled = true; let findings = []; document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk, idx) => { if (chk.checked) { let parts = chk.value.split('|'); let noteText = document.getElementById(`note_${idx}`) ? document.getElementById(`note_${idx}`).value : "تم الرصد"; let actionText = document.getElementById(`actionTaken_${idx}`) ? document.getElementById(`actionTaken_${idx}`).value : ""; let statusElem = document.getElementById(`status_${idx}`); let st = statusElem ? statusElem.value : "مفتوح"; if (actionText.includes("تم تلافي")) st = "مغلق"; let combinedNote = `الملاحظة: ${noteText} - الإجراء: ${actionText || 'لم يحدد'} - تاريخ التلافي: ${st === 'مغلق' ? new Date().toISOString().split('T')[0] : 'غير محدد'}`; findings.push({ category: parts[0], item: parts[1], note: combinedNote, location: document.getElementById(`loc_${idx}`) ? document.getElementById(`loc_${idx}`).value || "-" : "-", responsible: document.getElementById(`resp_${idx}`) ? document.getElementById(`resp_${idx}`).value || "-" : "-", status: st }); } }); let reportId = isDailyEditMode ? currentDailyEditId : Date.now(); const report = { id: reportId, date: document.getElementById('dailyDate').value, time: document.getElementById('dailyTime').value, shift: document.getElementById('dailyShift').value, inspector: document.getElementById('dailyInspector').value, findings: findings }; let actionType = isDailyEditMode ? "updateDailyInspection" : "submitDailyInspection"; try { await fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: actionType, reportData: report }), headers: { "Content-Type": "text/plain;charset=utf-8" } }); if (isDailyEditMode) { let editIdx = globalDailyInspections.findIndex(r => String(r.id) === String(reportId)); if (editIdx !== -1) globalDailyInspections[editIdx] = report; } else { globalDailyInspections.unshift(report); } document.getElementById('dailyMsg').style.color = "green"; document.getElementById('dailyMsg').innerText = "✅ تم حفظ الجولة بنجاح!"; setTimeout(() => { clearDailyFormForNew(); renderSavedDaily(); document.getElementById('dailyMsg').innerText = ""; }, 1500); } catch (err) { btn.disabled = false; document.getElementById('dailyMsg').style.color = "red"; document.getElementById('dailyMsg').innerText = "❌ حدث خطأ في الاتصال بالسيرفر."; } }

function editDailyInspection(reportId) { let rep = globalDailyInspections.find(r => String(r.id) === String(reportId)); if (!rep) return alert("لم يتم العثور على الجولة!"); switchDailyTab('entry'); document.getElementById('dailyForm').reset(); document.querySelectorAll('.check-inputs').forEach(el => el.style.display = 'none'); document.getElementById('dailyDate').value = rep.date ? rep.date.split('T')[0] : ''; document.getElementById('dailyTime').value = rep.time || ''; document.getElementById('dailyShift').value = rep.shift || 'صباحي'; document.getElementById('dailyInspector').value = rep.inspector || ''; document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk, idx) => { let parts = chk.value.split('|'); let found = rep.findings.find(f => f.category === parts[0] && f.item === parts[1]); if (found) { chk.checked = true; let inputGroup = document.getElementById(`inputs_${idx}`); if (inputGroup) { inputGroup.style.display = 'flex'; let nText = found.item, aText = ""; try { let match = (found.note || "").match(/الملاحظة:\s*(.*?)\s*-\s*الإجراء:\s*(.*?)\s*-\s*تاريخ التلافي:/); if (match) { nText = match[1]; aText = match[2]; } else { nText = found.note || ""; } } catch (e) {} document.getElementById(`note_${idx}`).value = nText; document.getElementById(`loc_${idx}`).value = found.location || ""; document.getElementById(`resp_${idx}`).value = found.responsible || ""; let isClosed = found.status === 'مغلق' || (found.note && found.note.includes('تم تلافي')); let statusElem = document.getElementById(`status_${idx}`); if (statusElem) statusElem.value = isClosed ? 'مغلق' : 'مفتوح'; let btn = document.getElementById(`rectifyBtn_${idx}`); if (btn) { if (isClosed) { btn.style.backgroundColor = '#155724'; btn.innerHTML = `<i class="fa-solid fa-check-double"></i> تم تلافي وإغلاق الملاحظة`; } else { btn.style.backgroundColor = '#28a745'; btn.innerHTML = `<i class="fa-solid fa-circle-check"></i> إغلاق وتلافي هذه الملاحظة الآن`; } } } } }); isDailyEditMode = true; currentDailyEditId = rep.id; let sBtn = document.getElementById('submitDailyBtn'); sBtn.disabled = false; sBtn.innerHTML = '<i class="fa-solid fa-pen-to-square"></i> حفظ التعديلات'; sBtn.style.backgroundColor = "#ffc107"; sBtn.style.color = "#000"; window.scrollTo({ top: document.getElementById('dailyForm').offsetTop - 30, behavior: 'smooth' }); }

function renderSavedDaily() { const tbody = document.getElementById('saved-daily-tbody'); if (!tbody) return; tbody.innerHTML = ""; if (globalDailyInspections.length === 0) { tbody.innerHTML = "<tr><td colspan='6' style='color:#777; font-weight:bold; text-align:center;'>لا توجد فحوصات محفوظة.</td></tr>"; return; } globalDailyInspections.forEach((rep) => { let openCount = 0, closedCount = 0; rep.findings.forEach(f => { if (f.status === 'مغلق' || (f.note && f.note.includes('تم تلافي'))) closedCount++; else openCount++; }); let badge = rep.findings.length === 0 ? `<span style="background:#28a745; color:white; padding:4px 10px; border-radius:12px; font-weight:bold; font-size:11px;">سليم 100%</span>` : (openCount === 0 && closedCount > 0 ? `<span style="background:#28a745; color:white; padding:4px 10px; border-radius:12px; font-weight:bold; font-size:11px;">تم تلافي الكل (${closedCount})</span>` : (openCount > 0 && closedCount > 0 ? `<span style="background:#dc3545; color:white; padding:3px 7px; border-radius:8px; font-size:11px; font-weight:bold;">${openCount} مفتوحة</span> <span style="background:#28a745; color:white; padding:3px 7px; border-radius:8px; font-size:11px; font-weight:bold;">${closedCount} تم تلافيها</span>` : `<span style="background:#dc3545; color:white; padding:4px 10px; border-radius:12px; font-weight:bold; font-size:11px;">${openCount} مخالفة مفتوحة</span>`)); let cleanDate = rep.date ? rep.date.split('T')[0] : ''; let cleanTime = rep.time || ''; tbody.innerHTML += `<tr><td dir="ltr" style="text-align:center;">${cleanDate}</td><td dir="ltr" style="text-align:center;">${cleanTime}</td><td style="text-align:center;">${rep.shift}</td><td style="text-align:center;">${rep.inspector}</td><td style="text-align:center;">${badge}</td><td style="text-align:center; white-space:nowrap;"><button type="button" onclick="editDailyInspection('${rep.id}')" style="background:#ffc107; color:#000; border:none; padding:5px 10px; border-radius:4px; cursor:pointer; font-weight:bold;" title="تعديل"><i class="fa-solid fa-pen-to-square"></i> تعديل</button> <button type="button" onclick="cloneDailyInspection('${rep.id}')" style="background:#17a2b8; color:#fff; border:none; padding:5px 10px; border-radius:4px; cursor:pointer;" title="نسخ الملاحظات ليوم جديد"><i class="fa-solid fa-copy"></i> نسخ لليوم</button> <button type="button" onclick="deleteDailyInspection('${rep.id}')" style="background:#dc3545; color:#fff; border:none; padding:5px 8px; border-radius:4px; cursor:pointer;" title="إلغاء"><i class="fa-solid fa-trash"></i> إلغاء</button></td></tr>`; }); }

function quickCloseFinding(chkIdx){let statusSel=document.getElementById(`status_${chkIdx}`);let targetDateField=document.getElementById(`targetDate_${chkIdx}`);let actionField=document.getElementById(`actionTaken_${chkIdx}`);let todayStr=new Date().toISOString().split('T')[0];if(statusSel){statusSel.value="مغلق";if(typeof updateStatusColor==='function')updateStatusColor(statusSel);else{statusSel.style.backgroundColor="#28a745";statusSel.style.color="#fff";}}if(targetDateField&&(!targetDateField.value||targetDateField.value===""))targetDateField.value=todayStr;if(actionField){let act=actionField.value.trim();if(!act.includes("تم تلافي"))actionField.value=(act===""||act==="لم يحدد"?"تم التلافي والإصلاح":act)+` [تم تلافي الملحوظة بتاريخ ${todayStr}]`;}alert("✅ تم تحويل الملاحظة إلى (مغلق) وتحديد تاريخ التلافي. اضغط على زر (حفظ التعديلات) بالأسفل لتثبيتها.");}

async function deleteDailyInspectionRecord(idx){if(!globalDailyInspections||!globalDailyInspections[idx])return;let rep=globalDailyInspections[idx];if(!confirm(`⚠️ هل أنت متأكد من إلغاء وحذف جولة يوم (${rep.date} - وردية ${rep.shift}) نهائياً؟`))return;let repId=rep.id;globalDailyInspections.splice(idx,1);renderSavedDaily();if(typeof updateDailyNavCounter==='function')updateDailyNavCounter();if(typeof generateMonthlyReport==='function')generateMonthlyReport();try{await fetch(API_URL,{method:'POST',body:JSON.stringify({action:"deleteDailyInspection",id:repId}),headers:{"Content-Type":"text/plain;charset=utf-8"}});}catch(e){console.error(e);}}

function copyDailyInspection(idx){let rep=globalDailyInspections[idx];if(!rep)return;if(!confirm(`هل تريد نسخ ملاحظات جولة يوم (${rep.date}) إلى جولة فحص جديدة بتاريخ اليوم؟`))return;if(typeof clearDailyFormForNew==='function')clearDailyFormForNew();if(typeof switchDailyTab==='function')switchDailyTab('entry');if(typeof autoFillDailyDateTime==='function')autoFillDailyDateTime();const dS=document.getElementById('dailyShift'),dI=document.getElementById('dailyInspector');if(dS)dS.value=rep.shift||'صباحي';if(dI)dI.value=rep.inspector||'';let count=0;if(rep.findings&&rep.findings.length>0){document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach((chk,chkIdx)=>{let parts=chk.value.split('|');let cat=parts[0].trim(),itm=parts[1].trim();let found=rep.findings.find(x=>(x.category||'').trim()===cat&&(x.item||'').trim()===itm);if(found){chk.checked=true;let inDiv=document.getElementById(`inputs_${chkIdx}`);if(inDiv)inDiv.style.display='flex';let fn=found.note||"",nT="تم الرصد",aT="لم يحدد",tD="";try{let m=fn.match(/الملاحظة: (.*?) - الإجراء: (.*?) - تاريخ التلافي: (.*)/);if(m){nT=m[1];aT=m[2];tD=m[3]!=="غير محدد"?m[3]:"";}else{nT=fn;}}catch(e){}if(document.getElementById(`note_${chkIdx}`))document.getElementById(`note_${chkIdx}`).value=nT;if(document.getElementById(`actionTaken_${chkIdx}`))document.getElementById(`actionTaken_${chkIdx}`).value=aT;if(document.getElementById(`targetDate_${chkIdx}`))document.getElementById(`targetDate_${chkIdx}`).value=tD;if(document.getElementById(`loc_${chkIdx}`))document.getElementById(`loc_${chkIdx}`).value=found.location||"";if(document.getElementById(`resp_${chkIdx}`))document.getElementById(`resp_${chkIdx}`).value=found.responsible||"";let st=document.getElementById(`status_${chkIdx}`);if(st){st.value=found.status||"مفتوح";if(typeof updateStatusColor==='function')updateStatusColor(st);}count++;}});}isDailyEditMode=false;currentDailyEditId=null;let btn=document.getElementById('submitDailyBtn');if(btn){btn.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ الجولة المنسوخة كفحص جديد اليوم';btn.style.backgroundColor="#28a745";btn.style.color="#fff";}const f=document.getElementById('dailyForm');if(f)f.scrollIntoView({behavior:'smooth',block:'start'});alert(`✅ تم نسخ (${count}) مخالفة إلى جولة فحص جديدة بتاريخ اليوم.`);}

function previewDailyReport(idx){if(!globalDailyInspections||!globalDailyInspections[idx])return;let rep=globalDailyInspections[idx];generateIsoDailyReport(rep);}

function printDailyIsoDirect(dt,shift){const dInp=document.getElementById('isoReportDate'),sInp=document.getElementById('isoReportShift');if(dInp&&dt)dInp.value=dt;if(sInp&&shift)sInp.value=shift;let rep=globalDailyInspections.find(r=>r.date===dt&&(shift?r.shift===shift:true))||globalDailyInspections.find(r=>r.date===dt);if(rep)generateIsoDailyReport(rep);else generateIsoDailyReport();}

function deleteDailyInspectionRecord(idx){if(!confirm("تأكيد الحذف؟"))return;let repId=globalDailyInspections[idx].id;globalDailyInspections.splice(idx,1);renderSavedDaily();updateDailyNavCounter();safePost({action:"updateDailyInspection",reportData:{id:repId,findings:[]}});}

function generateIsoDailyReport(specificRep){let rep=specificRep,targetD='',targetS='صباحي';if(!rep){targetD=document.getElementById('isoReportDate')?.value||'';targetS=document.getElementById('isoReportShift')?.value||'صباحي';if(!targetD&&typeof globalDailyInspections!=='undefined'&&globalDailyInspections.length>0){let validReps=globalDailyInspections.filter(r=>r&&r.date&&r.date!=='-');if(validReps.length>0){targetD=validReps[0].date;targetS=validReps[0].shift||'صباحي';}}if(document.getElementById('isoReportDate')&&targetD)document.getElementById('isoReportDate').value=targetD;if(document.getElementById('isoReportShift'))document.getElementById('isoReportShift').value=targetS;if(typeof globalDailyInspections!=='undefined'&&globalDailyInspections.length>0){rep=globalDailyInspections.find(r=>r.date===targetD&&r.shift===targetS)||globalDailyInspections.find(r=>r.date===targetD)||globalDailyInspections[0];}}if(!rep)return;let container=document.getElementById('printable-daily-report')||document.getElementById('printable-checklist-report')||document.querySelector('.iso-report-container');if(container)container.style.display='block';let dParts=(rep.date||'').split('-');let dispDate=dParts.length===3?`${dParts[2]} / ${dParts[1]} / ${dParts[0]}`:rep.date;let isMorn=(String(rep.shift||'').trim()==='صباحي');let targetArea=container||document;targetArea.querySelectorAll('*').forEach(el=>{if(el.children.length<=1){let txt=(el.innerText||'').trim();if(txt.includes('التاريخ')||txt.includes('28 / 10 / 2026')||/28\s*[\/\-]\s*10\s*[\/\-]\s*2026/.test(txt)){if(!txt.includes('AS-')&&!txt.includes('تلافي')){el.innerText=`التاريخ: ${dispDate}`;}}if(txt.includes('توقيع القائم بالتفتيش:')){el.innerHTML=`توقيع القائم بالتفتيش: <b style="color:#003366;">${rep.inspector||'............................'}</b>`;}}let html=el.innerHTML||'';if(el.children.length<=4&&(html.includes('وردية صباحي')||html.includes('وردية مسائي'))){el.innerHTML=html.replace(/[☑☐]?\s*وردية صباحي/g,(isMorn?'☑':'☐')+' وردية صباحي').replace(/[☑☐]?\s*وردية مسائي/g,(!isMorn?'☑':'☐')+' وردية مسائي');}});targetArea.querySelectorAll('input[type="checkbox"]').forEach(cb=>{let pText=(cb.parentElement?cb.parentElement.innerText:'')+' '+(cb.nextSibling?cb.nextSibling.textContent:'');if(pText.includes('صباحي'))cb.checked=isMorn;if(pText.includes('مسائي'))cb.checked=!isMorn;});let chkData=(typeof dailyChecklistData!=='undefined')?dailyChecklistData:null;if(!chkData){chkData={};document.querySelectorAll('#checklist-container input[type="checkbox"]').forEach(chk=>{let p=chk.value.split('|');if(p.length>=2){let cat=p[0].trim(),itm=p[1].trim();if(!chkData[cat])chkData[cat]={title:cat,items:[]};if(!chkData[cat].items.includes(itm))chkData[cat].items.push(itm);}});}let chkTable=document.getElementById('iso-checklist-table')||(container?container.querySelector('.iso-checklist-table'):null);if(!chkTable&&container){let noteEl=Array.from(container.querySelectorAll('*')).find(el=>el.innerText&&el.innerText.includes('ملحوظة (كل نقطة بعدم المطابقة')&&el.children.length===0);if(noteEl){chkTable=document.createElement('table');chkTable.id='iso-checklist-table';chkTable.style.cssText="width:100%;border-collapse:collapse;margin:10px auto 12px;font-size:9px;border:1px solid #000;direction:rtl;";noteEl.parentElement.insertBefore(chkTable,noteEl);}}if(chkTable&&chkData){let keys=Object.keys(chkData);let trH='<tr style="background:#f2f2f2;">';keys.forEach(k=>{let title=chkData[k].title||k;trH+=`<th style="border:1px solid #000;padding:4px 2px;text-align:center;font-size:9.5px;font-weight:bold;">${title}</th>`;});trH+='</tr>';let trB='<tr>';keys.forEach(k=>{let cData=chkData[k];let cell='<td style="border:1px solid #000;vertical-align:top;padding:2px;">';const renderList=(itemsArr,catTitle)=>{if(!itemsArr)return;itemsArr.forEach(itm=>{let isF=rep.findings&&rep.findings.some(f=>(f.category||'').trim()===catTitle.trim()&&(f.item||'').trim()===itm.trim());let bg=isF?'background:#ffebee;':'';let col=isF?'color:#dc3545;font-weight:bold;':'color:#000;';cell+=`<div class="checklist-row-print" style="display:flex;justify-content:space-between;align-items:center;padding:1.5px 2px;border-bottom:1px solid #eee;font-size:8.5px;${bg}"><span style="${col}">${itm}</span><input type="checkbox" checked disabled style="width:12px;height:12px;margin:0;"></div>`;});};if(cData.items){renderList(cData.items,cData.title||k);if(cData.title2&&cData.items2){cell+=`<div style="text-align:center;font-weight:bold;background:#e6e6e6;margin:3px -2px 2px;padding:2px;font-size:8.5px;">${cData.title2}</div>`;renderList(cData.items2,cData.title2);}if(cData.title3&&cData.items3){cell+=`<div style="text-align:center;font-weight:bold;background:#e6e6e6;margin:3px -2px 2px;padding:2px;font-size:8.5px;">${cData.title3}</div>`;renderList(cData.items3,cData.title3);}}else if(Array.isArray(cData)){renderList(cData,k);}cell+='</td>';trB+=cell;});trB+='</tr>';chkTable.innerHTML=trH+trB;}let fTable=null;targetArea.querySelectorAll('table').forEach(t=>{let txt=t.innerText||'';if(txt.includes('تفاصيل عدم المطابقة')||txt.includes('المنطقة / المكان')||t.id==='corrective-tbody'||t.id==='iso-bottom-findings-table')fTable=t;});let tb=document.getElementById('corrective-tbody');if(!tb&&fTable){tb=fTable.querySelector('tbody')||fTable;}if(tb){tb.innerHTML='';if(!rep.findings||rep.findings.length===0){tb.innerHTML='<tr><td colspan="5" style="text-align:center;padding:12px;font-weight:bold;color:#28a745;font-size:11px;">سليم 100% ولا توجد ملاحظات عدم مطابقة</td></tr>';}else{let seq=1;rep.findings.forEach(f=>{let fn=f.note||'',nT=fn,aT='لم يحدد',tD='';try{let m=fn.match(/الملاحظة: (.*?) - الإجراء: (.*?) - تاريخ التلافي: (.*)/);if(m){nT=m[1];aT=m[2];tD=(m[3]!=='غير محدد')?m[3]:'';}else{nT=fn;}}catch(e){}let stStr=String(f.status||f.Status||'').trim().toLowerCase();let clMatch=aT.match(/\[تم تلافي الملحوظة بتاريخ (.*?)\]/)||fn.match(/\[تم تلافي الملحوظة بتاريخ (.*?)\]/);let rawClDate=clMatch?clMatch[1]:(tD&&tD!==''?tD:rep.date);let clDate=rawClDate;if(clDate&&clDate.includes('-')){let cp=clDate.split('-');if(cp.length===3)clDate=`${cp[2]}/${cp[1]}/${cp[0]}`;}let isCl=(stStr==='مغلق'||stStr==='closed'||fn.includes('تم تلافي')||aT.includes('تم تلافي'));let stBadge=isCl?'<span style="color:#28a745;font-weight:900;font-size:11px;background:#e8f5e9;padding:2px 6px;border-radius:4px;border:1px solid #28a745;">مغلق</span>':'<span style="color:#dc3545;font-weight:900;font-size:11px;background:#ffebee;padding:2px 6px;border-radius:4px;border:1px solid #dc3545;">مفتوح</span>';let clNoteHtml=isCl?`<div style="color:#155724;background:#d4edda;border:1px solid #c3e6cb;font-weight:bold;font-size:9.5px;margin-top:4px;padding:3px 8px;border-radius:4px;display:inline-block;"><i class="fa-solid fa-check-double"></i> تم تلافي الملحوظة بتاريخ ${clDate}</div>`:'';let cleanAct=aT.replace(/\[تم تلافي الملحوظة بتاريخ.*?\]/g,'').trim();let actText=(cleanAct!=='لم يحدد'&&cleanAct!=='')?`<br><span style="color:#555;font-size:9px;">${cleanAct}</span>`:'';tb.innerHTML+=`<tr><td style="text-align:center;width:5%;padding:6px;border:1px solid #000;font-weight:bold;">${seq++}</td><td style="text-align:center;width:15%;padding:6px;border:1px solid #000;font-weight:bold;">${f.location||'-'}</td><td style="text-align:right;width:45%;padding:6px;border:1px solid #000;line-height:1.4;"><span style="color:#dc3545;font-weight:bold;font-size:10px;">${f.category} - ${f.item}</span><br><span style="color:#333;font-size:9.5px;">(${nT})</span><br>${clNoteHtml}</td><td style="text-align:center;width:15%;padding:6px;border:1px solid #000;">${f.responsible||'-'}</td><td style="text-align:center;width:20%;padding:6px;border:1px solid #000;">${stBadge}${actText}</td></tr>`;});}}if(container)container.scrollIntoView({behavior:'smooth',block:'start'});}

function exportIsoDailyPDF(){exportIsoform();}

function switchIncidentTab(t){document.querySelectorAll('#incident-section .tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('#incident-section .tab-content').forEach(c=>c.classList.remove('active'));document.getElementById('btn-inc-'+t)?.classList.add('active');document.getElementById('tab-inc-'+t)?.classList.add('active');if(t==='monthly')renderSavedIncidents();}

function updateIncidentNavCounter(){const el=document.getElementById('nav-incident-counter');const len=(globalIncidents&&globalIncidents.length)?globalIncidents.length:0;if(el)el.innerText=len>0?(currentIncidentIndex>=0?`${currentIncidentIndex+1} / ${len}`:`0 / ${len}`):`0 / 0`;}

function navIncidents(dir){const list=globalIncidents||[];if(!list||list.length===0)return alert("لا توجد وقائع مسجلة بعد.");if(dir==='first')currentIncidentIndex=0;else if(dir==='last')currentIncidentIndex=list.length-1;else if(dir==='next'&&currentIncidentIndex<list.length-1)currentIncidentIndex++;else if(dir==='prev'&&currentIncidentIndex>0)currentIncidentIndex--;if(currentIncidentIndex>=0&&currentIncidentIndex<list.length){loadIncidentToForm(currentIncidentIndex);switchIncidentTab('entry');}}

function removeCurrentIncidentAttachment(){if(!confirm("هل تريد بالتأكيد إزالة هذا المرفق من الواقعة؟"))return;const aInp=document.getElementById('incAttach');if(aInp)aInp.value='';const fInp=document.getElementById('incFileInp');if(fInp)fInp.value='';const pEl=document.getElementById('incAttachmentPreview');if(pEl)pEl.innerHTML='<span style="color:#dc3545;font-weight:bold;"><i class="fa-solid fa-circle-xmark"></i> تم مسح المرفق (اضغط "تحديث الواقعة" بالأسفل لتأكيد الحذف بالشيت)</span>';}

function loadIncidentToForm(idx){if(idx<0||!globalIncidents||idx>=globalIncidents.length)return;currentIncidentIndex=idx;let inc=globalIncidents[idx];currentIncidentEditId=inc.ID||inc.id;const s=(id,val)=>{const el=document.getElementById(id);if(el)el.value=val||'';};s('incId',inc.ID||inc.id);s('incDate',(inc.Date||inc.date||'').toString().split('T')[0]);s('incTime',inc.Time||inc.time);s('incLocation',inc.Location||inc.location);s('incPersonnel',inc.Personnel_Involved||inc.personnel);s('incPosition',inc.Position||inc.position);s('incInjuryType',inc.Injury_Type||inc.injuryType);s('incAcType',inc.TYPE||inc.type);s('incFlightNo',inc.Flight_No||inc.flightNo);s('incReg',inc.REG||inc.reg);s('incCar',inc.CAR||inc.car);s('incEquipmentNo',inc.Equipment_No||inc.equipmentNo);s('incDriver',inc.Driver_Name||inc.driver);s('incEqOwner',inc.Equipment_Owned||inc.eqOwner);s('incStatus',inc.Status||inc.status);s('incPreparedBy',inc.Prepared_By||inc.preparedBy);s('incChar',inc.Characterization||inc.charaterization);s('incCauses',inc.Occurrence_Causes||inc.causes);s('incRiskSev',inc.Risk_Severity||inc.riskSeverity);s('incRiskProb',inc.Risk_Probability||inc.riskProb);const attUrl=inc.Attachment_URL||inc.attachment_URL||'';s('incAttach',attUrl);s('incDesc',inc.Description||inc.description);s('incHazardDesc',inc.Hazard_Description||inc.hazardDesc);s('incCausesDetails',inc.Causes_Details||inc.causesDetails);s('incAction',inc.Action_Taken||inc.actionTaken);s('incRecommendation',inc.Recommendation||inc.recommendation);const prevEl=document.getElementById('incAttachmentPreview');if(prevEl){if(attUrl&&attUrl.length>5){let vLink=attUrl.startsWith('data:')?'#':attUrl;let tTarget=attUrl.startsWith('data:')?'':'_blank';prevEl.innerHTML=`<div style="display:flex;gap:10px;align-items:center;margin-top:5px;"><a href="${vLink}" target="${tTarget}" onclick="${attUrl.startsWith('data:')?'window.open().document.write(\\\'<img src=\\\x22'+attUrl+'\\\x22>\\\')':''}" style="color:#003366;font-weight:bold;text-decoration:underline;"><i class="fa-solid fa-eye"></i> معاينة المرفق الحالي 👁️</a><button type="button" onclick="removeCurrentIncidentAttachment()" style="background:#dc3545;color:#fff;border:none;padding:3px 10px;border-radius:4px;cursor:pointer;font-size:10.5px;font-weight:bold;"><i class="fa-solid fa-trash"></i> حذف المرفق</button></div>`;}else{prevEl.innerHTML=`<span style="color:#888;">لا يوجد مرفق محفوظ لهذه الواقعة</span>`;}}const fInp=document.getElementById('incFileInp');if(fInp)fInp.value='';const btn=document.getElementById('submitIncBtn');if(btn){btn.innerHTML='<i class="fa-solid fa-pen-to-square"></i> تحديث الواقعة';btn.style.backgroundColor='#17a2b8';}updateIncidentNavCounter();}

function clearIncidentForm(){currentIncidentIndex=-1;currentIncidentEditId=null;const f=document.getElementById('incidentForm');if(f)f.reset();const idF=document.getElementById('incId');if(idF)idF.value='';const dtF=document.getElementById('incDate');if(dtF)dtF.value=new Date().toISOString().split('T')[0];const fInp=document.getElementById('incFileInp');if(fInp)fInp.value='';const prevEl=document.getElementById('incAttachmentPreview');if(prevEl)prevEl.innerHTML='';const b=document.getElementById('submitIncBtn');if(b){b.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> حفظ الواقعة وتحديث السجل';b.style.backgroundColor='#dc3545';}updateIncidentNavCounter();switchIncidentTab('entry');}

function handleIncidentFileSelect(input){const prevEl=document.getElementById('incAttachmentPreview');if(!prevEl)return;if(input.files&&input.files[0]){prevEl.innerHTML=`<span style="color:#e67e22;font-weight:bold;"><i class="fa-solid fa-file-arrow-up"></i> تم اختيار ملف: ${input.files[0].name} (سيتم رفعه عند الحفظ)</span>`;}}

function processFileForUpload(file){return new Promise(res=>{if(!file.type.startsWith('image/')){const r=new FileReader();r.onload=()=>res({data:r.result,name:file.name,type:file.type});r.onerror=()=>res(null);r.readAsDataURL(file);return;}const r=new FileReader();r.onload=e=>{const img=new Image();img.onload=()=>{const maxD=1600;let w=img.width,h=img.height;if(w>maxD||h>maxD){if(w>h){h=Math.round(h*maxD/w);w=maxD;}else{w=Math.round(w*maxD/h);h=maxD;}}const cvs=document.createElement('canvas');cvs.width=w;cvs.height=h;const ctx=cvs.getContext('2d');ctx.drawImage(img,0,0,w,h);res({data:cvs.toDataURL('image/jpeg',0.85),name:file.name.replace(/\.[^/.]+$/,"")+".jpg",type:"image/jpeg"});};img.onerror=()=>res({data:e.target.result,name:file.name,type:file.type});img.src=e.target.result;};r.readAsDataURL(file);});}

async function saveIncident(e){if(e){e.preventDefault();e.stopPropagation();}const btn=document.getElementById('submitIncBtn')||event?.target?.closest('button');if(btn){btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> جاري حفظ الواقعة والمرفقات...';}const g=(id)=>document.getElementById(id)?.value?.trim()||'';const date=g('incDate')||new Date().toISOString().split('T')[0];const desc=g('incDesc')||'-';const incId=currentIncidentEditId||g('incId')||("INC-"+Date.now());let fileData=null,fileName='',mimeType='';const fileInp=document.getElementById('incFileInp');if(fileInp&&fileInp.files&&fileInp.files[0]){const upObj=await processFileForUpload(fileInp.files[0]);if(upObj){fileData=upObj.data;fileName=upObj.name;mimeType=upObj.type;}}const finalAttachment=fileData||g('incAttach')||'';const incObj={id:incId,date:date,time:g('incTime')||'',location:g('incLocation')||'Apron',personnel:g('incPersonnel')||'Nil',equipmentNo:g('incEquipmentNo')||'Nil',driver:g('incDriver')||'Nil',eqOwner:g('incEqOwner')||'EMAAS handling company',status:g('incStatus')||'In service',causes:g('incCauses')||'Human Causes',charaterization:g('incChar')||'Equipment Accident',riskSeverity:g('incRiskSev')||'Minor',riskProb:g('incRiskProb')||'Remote',checkboxes:'',car:g('incCar')||'-',flightNo:g('incFlightNo')||'-',reg:g('incReg')||'-',orgVia:'-',viaDst:'-',preparedBy:g('incPreparedBy')||'إدارة سلامة المطارات',hazardDesc:g('incHazardDesc')||'-',description:desc,actionTaken:g('incAction')||'-',recommendation:g('incRecommendation')||'-',attachment_URL:finalAttachment,position:g('incPosition')||'Nil',injuryType:g('incInjuryType')||'Nil',causesDetails:g('incCausesDetails')||'-',type:g('incAcType')||'-'};try{await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:currentIncidentEditId?"updateIncident":"submitIncident",incidentData:incObj,fileData:fileData,fileName:fileName,mimeType:mimeType})});if(!globalIncidents)globalIncidents=[];let exIdx=globalIncidents.findIndex(x=>(x.ID||x.id)===incId);let mapped={ID:incObj.id,Date:incObj.date,Time:incObj.time,Location:incObj.location,Personnel_Involved:incObj.personnel,Equipment_No:incObj.equipmentNo,Driver_Name:incObj.driver,Equipment_Owned:incObj.eqOwner,Status:incObj.status,Occurrence_Causes:incObj.causes,Characterization:incObj.charaterization,Risk_Severity:incObj.riskSeverity,Risk_Probability:incObj.riskProb,Checkboxes:'',CAR:incObj.car,Flight_No:incObj.flightNo,REG:incObj.reg,Prepared_By:incObj.preparedBy,Hazard_Description:incObj.hazardDesc,Description:incObj.description,Action_Taken:incObj.actionTaken,Recommendation:incObj.recommendation,Attachment_URL:finalAttachment,Position:incObj.position,Injury_Type:incObj.injuryType,Causes_Details:incObj.causesDetails,TYPE:incObj.type};if(exIdx>-1)globalIncidents[exIdx]=mapped;else globalIncidents.unshift(mapped);window.globalIncidents=globalIncidents;try{localStorage.setItem('rmf_incidents',JSON.stringify(globalIncidents));}catch(e){}sortIncidentsByDate();populateFilterSelect('incFilterCar',globalIncidents,'CAR','car');populateFilterSelect('incFilterReg',globalIncidents,'REG','reg');alert('✅ تم حفظ الواقعة وتحديث السجل وقاعدة البيانات بنجاح!');clearIncidentForm();renderSavedIncidents();switchIncidentTab('monthly');}catch(err){console.error(err);alert('❌ حدث خطأ أثناء الاتصال بالسيرفر لحفظ الواقعة.');}finally{if(btn)btn.disabled=false;}}

function submitIncident(e){saveIncident(e);}

function renderSavedIncidents(){const tb=document.getElementById('saved-inc-tbody');sortIncidentsByDate();let list=globalIncidents||[];const fChar=document.getElementById('incFilterChar')?.value||'ALL',fCau=document.getElementById('incFilterCauses')?.value||'ALL',fSev=document.getElementById('incFilterSev')?.value||'ALL',fProb=document.getElementById('incFilterProb')?.value||'ALL',fCar=document.getElementById('incFilterCar')?.value||'ALL',fReg=document.getElementById('incFilterReg')?.value||'ALL';list=list.filter(i=>{let cChar=fChar==='ALL'||(i.Characterization||i.charaterization)===fChar;let cCau=fCau==='ALL'||(i.Occurrence_Causes||i.causes)===fCau;let cSev=fSev==='ALL'||(i.Risk_Severity||i.riskSeverity)===fSev;let cProb=fProb==='ALL'||(i.Risk_Probability||i.riskProb)===fProb;let cCar=fCar==='ALL'||(i.CAR||i.car)===fCar;let cReg=fReg==='ALL'||(i.REG||i.reg)===fReg;return cChar&&cCau&&cSev&&cProb&&cCar&&cReg;});updateIncidentNavCounter();if(!tb)return;tb.innerHTML='';if(!list||list.length===0){tb.innerHTML='<tr><td colspan="6" style="text-align:center;padding:15px;color:#777;">لا توجد وقائع مطابقة للبحث</td></tr>';return;}list.forEach((item,idx)=>{const id=item.ID||item.id||`INC-${idx}`;const dt=(item.Date||item.date||'').toString().split('T')[0];const loc=item.Location||item.location||'-';const flt=item.Flight_No||item.flightNo||item.CAR||'';const locFlt=flt?`${loc} / ${flt}`:loc;const char=item.Characterization||item.charaterization||item.characterization||'-';const sev=item.Risk_Severity||item.riskSeverity||'-';const loss=item.Prepared_By||item.preparedBy||item.Personnel_Involved||'-';const sClr=sev==='Catastrophic'||sev==='Critical'?'#dc3545':(sev==='Major'?'#ffc107':'#28a745');tb.innerHTML+=`<tr style="border-bottom:1px solid #ddd;text-align:center;"><td style="padding:8px;" dir="ltr">${dt}</td><td style="padding:8px;font-weight:bold;">${locFlt}</td><td style="padding:8px;">${char}</td><td style="padding:8px;"><span style="background:${sClr};color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;">${sev}</span></td><td style="padding:8px;">${loss}</td><td style="padding:6px;display:flex;gap:4px;justify-content:center;align-items:center;"><button type="button" onclick="loadIncidentToForm(${idx});switchIncidentTab('entry');" title="عرض وتعديل الواقعة" style="background:#17a2b8;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-pen-to-square"></i></button><button type="button" onclick="printIsoIncidentReport('${id}')" title="طباعة تقرير ISO" style="background:#003366;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-print"></i></button><button type="button" onclick="exportIsoIncidentImage('${id}')" title="تصدير كصورة عريضة PNG" style="background:#28a745;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-file-image"></i></button><button type="button" onclick="deleteIncident('${id}')" title="حذف الواقعة" style="background:#dc3545;color:#fff;border:none;padding:5px 8px;border-radius:4px;cursor:pointer;"><i class="fa-solid fa-trash"></i></button></td></tr>`;});}

function renderIncidentsTable(){renderSavedIncidents();}

async function deleteIncident(incId){if(!confirm("⚠️ هل أنت متأكد من حذف هذه الواقعة نهائياً من قاعدة البيانات؟"))return;try{await fetch(API_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:"deleteIncident",id:incId})});if(globalIncidents){globalIncidents=globalIncidents.filter(x=>(x.ID||x.id)!==incId);window.globalIncidents=globalIncidents;try{localStorage.setItem('rmf_incidents',JSON.stringify(globalIncidents));}catch(e){}}alert("✅ تم حذف الواقعة بنجاح!");renderSavedIncidents();updateIncidentNavCounter();}catch(e){alert("❌ فشل الاتصال بالسيرفر لحذف الواقعة.");}}

